@pytest.mark.parametrize("rolling_attrs", [None, False, True])
@pytest.mark.parametrize("method_attrs", [None, False, True])
def test_rolling_keep_attrs_precedence(
    as_dataset, method, global_attrs, rolling_attrs, method_attrs
):
    array = xr.DataArray(
        [1.0, 3.0, 5.0],
        dims="time",
        name="foo",
        attrs={"units": "m"},
    )
    obj = array.to_dataset() if as_dataset else array
    if as_dataset:
        obj.attrs = {"title": "example"}
    original = obj.copy(deep=True)
    expected_attrs = global_attrs is True
    if rolling_attrs is not None:
        expected_attrs = rolling_attrs
    if method_attrs is not None:
        expected_attrs = method_attrs

    with xr.set_options(keep_attrs=global_attrs):
        rolling = obj.rolling(time=2, keep_attrs=rolling_attrs)
        if method == "construct":
            result = rolling.construct("window", keep_attrs=method_attrs)
            values = [[np.nan, 1.0], [1.0, 3.0], [3.0, 5.0]]
            dims = ("time", "window")
        else:
            if method == "reduce":
                result = rolling.reduce(np.mean, keep_attrs=method_attrs)
            else:
                result = getattr(rolling, method)(keep_attrs=method_attrs)
            values = {
                "mean": [np.nan, 2.0, 4.0],
                "reduce": [np.nan, 2.0, 4.0],
                "prod": [np.nan, 3.0, 15.0],
                "count": [np.nan, 2.0, 2.0],
            }[method]
            dims = ("time",)

    expected = xr.DataArray(
        values, dims=dims, name="foo", attrs=array.attrs if expected_attrs else {}
    )
    if as_dataset:
        expected = expected.to_dataset()
        expected.attrs = obj.attrs if expected_attrs else {}
    assert_identical(result, expected)
    assert_identical(obj, original)


