import numpy as np
import pytest

import xarray as xr
from xarray.testing import assert_identical


@pytest.mark.parametrize("method", ["mean", "prod", "reduce", "count", "construct"])
@pytest.mark.parametrize("keep_attrs", [False, True])
@pytest.mark.parametrize("with_coords", [False, True])
def test_dataarray_rolling_metadata(method, keep_attrs, with_coords):
    array = xr.DataArray(
        np.arange(1.0, 13.0).reshape(6, 2),
        dims=("time", "x"),
        coords={"time": np.arange(6), "x": [10, 20]} if with_coords else None,
        name="foo",
        attrs={"place": "here", "long_name": "test"},
    )
    rolling = array.rolling(time=2, keep_attrs=keep_attrs)
    if method == "construct":
        result = rolling.construct("window")
        values = np.full((6, 2, 2), np.nan)
        values[:, :, 1] = array.values
        values[1:, :, 0] = array.values[:-1]
        dims = array.dims + ("window",)
    else:
        if method == "reduce":
            result = rolling.reduce(np.mean)
        else:
            result = getattr(rolling, method)()
        values = np.full(array.shape, np.nan)
        if method in ("mean", "reduce"):
            values[1:] = (array.values[:-1] + array.values[1:]) / 2
        elif method == "prod":
            values[1:] = array.values[:-1] * array.values[1:]
        else:
            values[1:] = 2
        dims = array.dims
    expected = xr.DataArray(
        values,
        dims=dims,
        coords=array.coords,
        name=array.name,
        attrs=array.attrs if keep_attrs else {},
    )
    assert_identical(result, expected)
    assert array.attrs == {"place": "here", "long_name": "test"}

